import { Meteor } from 'meteor/meteor';
import { WebApp } from "meteor/webapp";
import axios from "axios";

Meteor.startup(async () => {
  console.log("["+(new Date().toLocaleString())+"] Meteor Server started")
})

// WebApp.handlers.use("/", async (req, res, next) => { ... })
Meteor.methods ({

  doThings: async function(uuids){

  /*
    if(!req.query.uuids){
      res.writeHead(400)
      res.end('No UUID provided')
      return
    }

    let uuids = req.query.uuids.split(',');
  */

    let apiKey = "Hx0vg3IKSbNLVwGftPZiIc8rjjbF1BGf"
    let orthancServerURL = 'https://breastscan.imaging.i3m.upv.es/orthanc-full/'
    // let orthancServerURL = 'https://admin:admon@orthanc-eucaim.grycap.i3m.upv.es/'
    // let orthancServerURL = 'http://admin:admon@localhost/'


    let r = "Query: " + JSON.stringify(req.query)
    r +=  "\nUUIDS: " + uuids

    console.log(r)
    // res.writeHead(200)
    // res.end(r)
    return r


    /* Retrieve project name */
    let system = (await axios.get(orthancServerURL+'system/')).data
    let project_name = system.Name.split('|')[0].trim()

    /* Retrieve studies from study UUIDS and series from serie UUIDS inside study (replacing the serie UUID by the serie object) */
    let studies = await Promise.all(uuids.map( async (uuid) => {
      let study = (await axios.get(orthancServerURL+'studies/' + uuid)).data
      study.Series = await Promise.all(study.Series.map( async (serie) =>
        (await axios.get(orthancServerURL+'series/' + serie)).data
      ))
      return study
    }))

    /* Retrieve subjects from studies and remove duplicates */
    let subjects = [...new Map(studies.map(study => [study.PatientMainDicomTags.PatientID, study.PatientMainDicomTags])).values()]



    /* Build body request to dataset service */
    let payload = {
      name: "",
      version: "?",
      project: project_name,
      previousId: "",
      description: "?",
      provenance: "?",
      purpose: "?",
      type: "",
      collectionMethod: "",
      studies: studies.map(study => ({
        studyId: study.ID,
        studyName: study.MainDicomTags.StudyInstanceUID,
        subjectName: study.PatientMainDicomTags.PatientName,
        pathInDatalake: study.PatientMainDicomTags.PatientName+"/"+study.MainDicomTags.StudyInstanceUID,
        series: study.Series.map( (serie) => ({
          folderName: study.PatientMainDicomTags.PatientName+"/"+study.MainDicomTags.StudyInstanceUID+"/"+serie.MainDicomTags.SeriesInstanceUID,
          tags: []
        })),
        url: Meteor.absoluteUrl()+"ohif/viewer?StudyInstanceUIDs="+study.MainDicomTags.StudyInstanceUID
      })),
      subjects: subjects.map(subject => ({
        subjectName: subject.PatientName,
        subjectId: subject.PatientID,
        eForm: {}
      }))
    }

    let response =  ""

    /*
    response += "--- SYSTEM ---\n\n"
    response += JSON.stringify(system, null, 2) + "\n\n\n"

    response += "--- STUDIES ---\n\n"
    response += JSON.stringify(studies, null, 2) + "\n\n\n"

    response += "--- SUBJECTS ---\n\n"
    response += JSON.stringify(subjects, null, 2) + "\n\n\n"
  */
    response += "--- PAYLOAD ---\n\n"
    response += JSON.stringify(payload, null, 2)

    console.log(response)

    //res.writeHead(200)
    //res.end(response)
  }

})

